import { AiVoiceMode } from "@/components/design-for-ai/ai-voice-mode";

// Your voice pipeline drives it: state, the turns so far and the live levels.
const analyser = audioCtx.createAnalyser(); // fed by getUserMedia
const buf = new Float32Array(analyser.fftSize);
const micRms = () => {
  analyser.getFloatTimeDomainData(buf);
  return Math.sqrt(buf.reduce((s, v) => s + v * v, 0) / buf.length);
};

<AiVoiceMode
  name="Marlo"
  state={state} // "idle" | "listening" | "thinking" | "speaking" | "interrupted"
  turns={turns} // [{ id, role: "user", text, interim }, { id, role: "assistant", text, spoken, cutAt }]
  getLevel={micRms} // sampled once a frame
  getOutputLevel={playbackRms}
  sensitivity={60} // noise gate at −44 dB
  onStart={openMic}
  onStop={sendTurn}
  onInterrupt={() => { player.stop(); markCut(); }}
  onEnd={closeSession}
/>

import { AuthOtp } from "@/components/design-for-ai/auth-otp";

<AuthOtp
  channel="email"
  destination={user.email}
  onVerify={async (code) => {
    const res = await fetch("/api/verify", { method: "POST", body: JSON.stringify({ code }) });
    if (res.status === 410) return { ok: false, reason: "expired" };
    if (res.status === 429) return { ok: false, reason: "locked" };
    if (!res.ok) return { ok: false, reason: "invalid", attemptsLeft: Number(res.headers.get("X-Attempts-Left")) };
    return { ok: true };
  }}
  onResend={() => fetch("/api/verify/resend", { method: "POST" }).then(() => undefined)}
  onChangeDestination={(email) => sendCode(email)}
  onVerified={() => router.push("/app")}
/>

